-- Tracelynt initial private-workspace schema.
-- IDs are generated by the application. This migration intentionally does not
-- create an authentication provider or expose any case API.
BEGIN;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  oidc_issuer text NOT NULL,
  oidc_subject text NOT NULL,
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended', 'deletion_pending')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (oidc_issuer, oidc_subject),
  CHECK (length(oidc_issuer) BETWEEN 1 AND 2048),
  CHECK (length(oidc_subject) BETWEEN 1 AND 512)
);

CREATE TABLE sessions (
  token_hash bytea PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  last_seen_at timestamptz,
  CHECK (octet_length(token_hash) = 32),
  CHECK (expires_at > created_at)
);
CREATE INDEX sessions_user_active_idx
  ON sessions (user_id, expires_at)
  WHERE revoked_at IS NULL;

CREATE TABLE cases (
  id uuid PRIMARY KEY,
  owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
  purpose text NOT NULL CHECK (length(btrim(purpose)) BETWEEN 1 AND 2000),
  subject_type text NOT NULL CHECK (subject_type IN ('business', 'domain', 'phone_number', 'other')),
  subject_label text NOT NULL CHECK (length(btrim(subject_label)) BETWEEN 1 AND 500),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'archived', 'deletion_pending')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  retention_deadline timestamptz
);
CREATE INDEX cases_owner_updated_idx ON cases (owner_user_id, updated_at DESC, id);

CREATE TABLE evidence_items (
  id uuid PRIMARY KEY,
  case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
  creator_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  claim text NOT NULL CHECK (length(btrim(claim)) BETWEEN 1 AND 5000),
  category text NOT NULL CHECK (category IN ('public_record', 'direct_observation', 'provider_data', 'user_report', 'analyst_assessment')),
  review_state text NOT NULL DEFAULT 'unreviewed'
    CHECK (review_state IN ('unreviewed', 'corroborated', 'disputed', 'unavailable', 'retracted')),
  source_name text NOT NULL CHECK (length(btrim(source_name)) BETWEEN 1 AND 300),
  source_url text,
  observed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  limitations text NOT NULL DEFAULT '' CHECK (length(limitations) <= 5000),
  correction_note text,
  retracted_at timestamptz,
  CHECK (source_url IS NULL OR length(source_url) <= 2048),
  CHECK (correction_note IS NULL OR length(correction_note) <= 2000)
);
CREATE INDEX evidence_case_created_idx ON evidence_items (case_id, created_at DESC, id);
CREATE INDEX evidence_creator_idx ON evidence_items (creator_user_id, created_at DESC);

CREATE TABLE report_versions (
  id uuid PRIMARY KEY,
  case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
  creator_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  version_number integer NOT NULL CHECK (version_number > 0),
  generated_at timestamptz NOT NULL DEFAULT now(),
  report_data jsonb NOT NULL CHECK (jsonb_typeof(report_data) = 'object'),
  deleted_at timestamptz,
  UNIQUE (case_id, version_number)
);
CREATE INDEX report_versions_case_idx ON report_versions (case_id, version_number DESC);

CREATE TABLE audit_events (
  id uuid PRIMARY KEY,
  actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  action text NOT NULL CHECK (length(action) BETWEEN 1 AND 100),
  resource_type text NOT NULL CHECK (resource_type IN ('case', 'evidence', 'report', 'session', 'account', 'export')),
  resource_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  outcome text NOT NULL CHECK (outcome IN ('success', 'denied', 'failure')),
  request_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object' AND octet_length(metadata::text) <= 4096),
  CHECK (request_id IS NULL OR length(request_id) <= 128)
);
CREATE INDEX audit_actor_time_idx ON audit_events (actor_user_id, occurred_at DESC);
CREATE INDEX audit_resource_time_idx ON audit_events (resource_type, resource_id, occurred_at DESC);

-- No public-link or sharing tables. Application queries must still scope every
-- case operation by authenticated owner; schema constraints alone are not auth.
COMMIT;
